#!/usr/bin/env python3
"""Embed the self-contained LAN chat page in the UWP binary; no packaging dependency."""
from pathlib import Path
root = Path(__file__).resolve().parent.parent
page = (root / 'uwp/web/chat.html').read_text()
assert ')XLLAMA_WEB"' not in page
header = ('// Copyright (c) 2024 Gianluca Mazza\n// SPDX-License-Identifier: MIT\n'
          '// Generated by scripts/embed-web-chat.py from uwp/web/chat.html.\n'
          '#pragma once\n// clang-format off\n'
          'namespace xllama::api {\n'
          'inline constexpr char kWebChatHtml[] = R"XLLAMA_WEB(' + page + ')XLLAMA_WEB";\n'
          '}\n// clang-format on\n')
(root / 'uwp/web-chat.generated.h').write_text(header)
